#!/bin/sh
# Generated by StackToIT from execution-plan.json. StackToIT has not run this script and runs none.
# Step: MAN/path/module.retail_app_ecs.module.alb.aws_lb.this/target-network/network-of-the-cluster
# What it does: after the stage of `execution/deploy.sh` that creates the SKE cluster (stackit_ske_cluster.retail_app_ecs_cluster) is applied, it reads the network SKE made for the cluster and the private addresses
# of its nodes, and writes alb_cluster_network_id, alb_target_ips as lines of the values file of the draft (default review/target-values.tfvars; one line `name = value` for each):
# a line of the file with that name is replaced, every other line stays, a name the file does not have is added. Run StackToIT again on the same
# output folder afterwards (it reads the file), and apply the rest of the draft.
# It only reads: `stackit network list` and `kubectl get nodes`. It creates, changes and deletes nothing in STACKIT or in the cluster; its one write is the
# values file. It prints no credential (the kubeconfig is only handed to kubectl).
# Needs: the stackit CLI logged in to the project, kubectl, jq.
# Environment: PROJECT_ID (the STACKIT project id), KUBECONFIG (the kubeconfig file of the cluster, see handover/cluster-access/kubeconfig.md),
# CLUSTER_NAME (the name of the cluster; default reta-7b7ce2, the name stackit_ske_cluster.retail_app_ecs_cluster writes), TARGET_VALUES (the values file).
# The addresses of the nodes change when the node pool scales or is updated (a node is added or replaced): after such a change run this script,
# StackToIT and the apply again; the targets of the load balancer are the addresses of the moment this script ran.
set -eu

fail() { printf '%s\n' "$1" >&2; exit "${2:-5}"; }

here=$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd)
values="${TARGET_VALUES:-$here/../../review/target-values.tfvars}"
cluster="${CLUSTER_NAME:-reta-7b7ce2}"
[ -n "$cluster" ] || fail 'CLUSTER_NAME is not set: the name of the SKE cluster stackit_ske_cluster.retail_app_ecs_cluster. Nothing was read.'
[ -n "${PROJECT_ID:-}" ] || fail 'PROJECT_ID is not set: the id of the STACKIT project. Nothing was read.'
[ -n "${KUBECONFIG:-}" ] || fail 'KUBECONFIG is not set: the kubeconfig file of the cluster (handover/cluster-access/kubeconfig.md). Nothing was read.'
[ -f "$KUBECONFIG" ] || fail 'KUBECONFIG is not a file. Nothing was read.'
for tool in stackit kubectl jq; do
  command -v "$tool" >/dev/null 2>&1 || fail "$tool is not installed. Nothing was read."
done

# the network SKE made for the cluster is the one named shoot--<hash>--<the name of the cluster> in the project's list (objects with "id" and "name")
networks=$(stackit network list --project-id "$PROJECT_ID" -o json) || fail 'stackit network list failed (is the CLI logged in to the project?). Nothing was written.'
net_ids=$(printf '%s' "$networks" | jq -r --arg c "$cluster" '(if type == "array" then . else (.items // []) end) | map(select((.name // "") | (startswith("shoot--") and endswith("--" + $c)))) | .[].id') || fail 'The answer of stackit network list is not JSON. Nothing was written.'
found=$(printf '%s\n' "$net_ids" | grep -c . || true)
[ "$found" = 1 ] || fail "Expected one network named shoot--<hash>--$cluster in the project, found $found. Nothing was written (the cluster is not created yet, or CLUSTER_NAME is not the cluster's name)." 6
case "$net_ids" in *[!0-9A-Fa-f-]*) fail 'The id of the network is not an id. Nothing was written.' 6;; esac

# the private addresses of the nodes: the InternalIP of every node
nodes=$(kubectl --kubeconfig "$KUBECONFIG" get nodes -o jsonpath='{range .items[*]}{.status.addresses[?(@.type=="InternalIP")].address}{"\n"}{end}') || fail 'kubectl get nodes failed. Nothing was written.'
nodes=$(printf '%s\n' "$nodes" | grep . | LC_ALL=C sort -u || true)
[ -n "$nodes" ] || fail 'The cluster lists no node with an InternalIP. Nothing was written.' 6
[ -z "$(printf '%s' "$nodes" | tr -d '0-9.\n')" ] || fail 'A node address is not an IPv4 address. Nothing was written.' 6
addresses=$(printf '%s\n' "$nodes" | awk 'NR > 1 { printf ", " } { printf "\"%s\"", $0 }')
count=$(printf '%s\n' "$nodes" | grep -c .)

# set_value NAME LINE: the first line of the file that sets NAME (`NAME = ...`, a list over several lines included) becomes LINE; else the line that
# StackToIT wrote for it as a comment (`# NAME = ...`) does; else LINE is added at the end. Every other line is kept.
set_value() {
  name=$1 newline=$2
  if [ ! -f "$values" ]; then printf '%s\n' "$newline" > "$values"; return; fi
  if grep -Eq "^[[:space:]]*${name}[[:space:]]*=" "$values"; then pattern="^[[:space:]]*${name}[[:space:]]*="
  elif grep -Eq "^#[[:space:]]*${name}[[:space:]]*=" "$values"; then pattern="^#[[:space:]]*${name}[[:space:]]*="
  else printf '%s\n' "$newline" >> "$values"; return; fi
  tmp="$values.tmp.$$"
  awk -v pattern="$pattern" -v newline="$newline" '
    skip { if ($0 ~ /\]/) skip = 0; next }
    !done && $0 ~ pattern { print newline; done = 1; if ($0 !~ /^#/ && $0 ~ /\[/ && $0 !~ /\]/) skip = 1; next }
    { print }
  ' "$values" > "$tmp" || { rm -f "$tmp"; fail 'Could not rewrite the values file. Nothing was changed.' 6; }
  cat "$tmp" > "$values" && rm -f "$tmp"
}

set_value alb_cluster_network_id "alb_cluster_network_id = \"$net_ids\""
set_value alb_target_ips "alb_target_ips = [$addresses]"

printf '%s\n' "Wrote alb_cluster_network_id, alb_target_ips (the network $net_ids) and the addresses of $count node(s) to $values."
printf '%s\n' "Next: run StackToIT again on the same output folder (it reads that file), then apply the rest of the draft (tofu apply in terraform/)."
